"""Borrows the general pasteboard for one Cmd+C and puts every item back afterwards."""
import threading
import time

import AppKit
import Quartz

KEY_C = 8  # ANSI layout position of "c"
# Password managers mark secrets with these. Never borrow a pasteboard holding one.
PRIVATE = {"org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
           "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"}
_borrow = threading.Lock()  # a triple-click starts two reads; one must not snapshot the other's copy


def _board():
    return AppKit.NSPasteboard.generalPasteboard()


def types():
    return {str(t) for item in (_board().pasteboardItems() or []) for t in item.types()}


def safe_to_borrow(kinds) -> bool:
    """False for secrets and for promised files, which can't be read back without blocking."""
    return not any(k in PRIVATE or "promise" in k.lower() for k in kinds)


def snapshot():
    return [[(t, item.dataForType_(t)) for t in item.types()] for item in (_board().pasteboardItems() or [])]


def restore(saved):
    board = _board()
    board.clearContents()
    items = []
    for entries in saved:
        item = AppKit.NSPasteboardItem.alloc().init()
        for kind, data in entries:
            if data is not None:
                item.setData_forType_(data, kind)
        items.append(item)
    if items:
        board.writeObjects_(items)


def _cmd_c():
    for down in (True, False):
        event = Quartz.CGEventCreateKeyboardEvent(None, KEY_C, down)
        Quartz.CGEventSetFlags(event, Quartz.kCGEventFlagMaskCommand)
        Quartz.CGEventPost(Quartz.kCGHIDEventTap, event)


def copy_selection() -> str:
    with _borrow:
        return _copy_selection()


def _copy_selection():
    if not safe_to_borrow(types()):
        return ""
    board = _board()
    saved, count = snapshot(), board.changeCount()
    _cmd_c()
    deadline = time.monotonic() + 0.3
    while board.changeCount() == count and time.monotonic() < deadline:
        time.sleep(0.01)
    if board.changeCount() == count:
        return ""  # nothing was selected, nothing was copied
    time.sleep(0.03)  # let the app finish writing every type
    try:
        if not safe_to_borrow(types()):
            return ""  # the source marked what it copied as a secret
        return str(board.stringForType_(AppKit.NSPasteboardTypeString) or "")
    finally:
        restore(saved)
